#include <stdio.h>

void countdown(int n) {
    if (n == 0) {
        printf("到站喵\n");
        return;
    }
    printf("%d\n", n);
    countdown(n - 1);
}

int main(void) {
    countdown(3);
    return 0;
}

#include <stdio.h>

void down(int n) {
    int mine = n * 10;
    if (n == 0) {
        printf("到底了，本喵碗里是 %d\n", mine);
        return;
    }
    printf("往下走之前，本喵碗里是 %d\n", mine);
    down(n - 1);
    printf("回来之后，本喵碗里还是 %d\n", mine);
}

int main(void) {
    down(2);
    return 0;
}
